import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { motion } from "framer-motion";
import { doc, getDoc } from "firebase/firestore";
import ReactMarkdown from "react-markdown";
import { db } from "../firebase";
import PageLayout from "../components/PageLayout";

const CATEGORY_COLORS = {
    "Quant": "bg-green-500/10 border-green-500/30 text-green-400",
    "ML/AI": "bg-blue-500/10 border-blue-500/30 text-blue-300",
    "Research": "bg-purple-500/10 border-purple-500/30 text-purple-300",
    "Tech": "bg-yellow-500/10 border-yellow-500/30 text-yellow-300",
    "General": "bg-gray-500/10 border-gray-500/30 text-gray-400",
};

function formatDate(ts) {
    if (!ts) return "";
    const d = ts.toDate ? ts.toDate() : new Date(ts);
    return d.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
}

export default function BlogPostPage() {
    const { id } = useParams();
    const [post, setPost] = useState(null);
    const [loading, setLoading] = useState(true);
    const [notFound, setNotFound] = useState(false);

    useEffect(() => {
        const fetchPost = async () => {
            try {
                const docRef = doc(db, "blogs", id);
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    setPost({ id: docSnap.id, ...docSnap.data() });
                } else {
                    setNotFound(true);
                }
            } catch (err) {
                console.error("Failed to fetch post:", err);
                setNotFound(true);
            } finally {
                setLoading(false);
            }
        };
        fetchPost();
    }, [id]);

    if (loading) {
        return (
            <PageLayout>
                <div className="text-center text-gray-500 py-20 font-mono">
                    <div className="text-2xl mb-2">⟳</div>
                    Loading...
                </div>
            </PageLayout>
        );
    }

    if (notFound || !post) {
        return (
            <PageLayout>
                <div className="text-center py-20">
                    <div className="text-5xl mb-4">404</div>
                    <p className="text-green-400 text-xl font-semibold mb-2">Post not found</p>
                    <Link to="/blogs" className="text-gray-400 hover:text-green-400 transition text-sm">
                        ← Back to all posts
                    </Link>
                </div>
            </PageLayout>
        );
    }

    return (
        <PageLayout>
            <motion.article
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6 }}
                className="max-w-3xl mx-auto"
            >
                {/* Meta */}
                <div className="flex flex-wrap items-center gap-3 mb-4">
                    {post.category && (
                        <span className={`border text-xs font-mono px-2.5 py-0.5 rounded-full ${CATEGORY_COLORS[post.category] || CATEGORY_COLORS["General"]}`}>
                            {post.category}
                        </span>
                    )}
                    <span className="text-gray-600 text-xs font-mono">{formatDate(post.date)}</span>
                    {post.author && (
                        <span className="text-gray-600 text-xs">by {post.author}</span>
                    )}
                </div>

                {/* Title */}
                <h1 className="text-3xl md:text-4xl font-bold text-green-400 mb-4 leading-tight">
                    {post.title}
                </h1>

                {/* Summary */}
                {post.summary && (
                    <p className="text-gray-300 text-lg leading-relaxed mb-8 pb-8 border-b border-green-500/10">
                        {post.summary}
                    </p>
                )}

                {/* Tags */}
                {post.tags && post.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1.5 mb-8">
                        {post.tags.map((tag) => (
                            <span key={tag} className="bg-[#0d1117] border border-green-500/20 text-gray-500 text-xs px-2.5 py-0.5 rounded-full font-mono">
                                #{tag}
                            </span>
                        ))}
                    </div>
                )}

                {/* Content */}
                <div className="prose-blog">
                    <ReactMarkdown>{post.content || ""}</ReactMarkdown>
                </div>

                {/* Back link */}
                <div className="mt-12 pt-8 border-t border-green-500/10">
                    <Link
                        to="/blogs"
                        className="text-green-400 hover:text-green-300 transition text-sm font-mono"
                    >
                        ← Back to all posts
                    </Link>
                </div>
            </motion.article>

            <style>{`
                .prose-blog { color: #d1d5db; line-height: 1.8; font-size: 1rem; }
                .prose-blog h1, .prose-blog h2, .prose-blog h3 { color: #4ade80; font-weight: 700; margin-top: 1.8em; margin-bottom: 0.6em; }
                .prose-blog h1 { font-size: 1.8rem; }
                .prose-blog h2 { font-size: 1.4rem; border-bottom: 1px solid rgba(34,197,94,0.15); padding-bottom: 0.4em; }
                .prose-blog h3 { font-size: 1.15rem; }
                .prose-blog p { margin-bottom: 1.2em; }
                .prose-blog ul, .prose-blog ol { padding-left: 1.5rem; margin-bottom: 1.2em; }
                .prose-blog li { margin-bottom: 0.3em; }
                .prose-blog code { background: #0d1117; border: 1px solid rgba(34,197,94,0.2); color: #4ade80; padding: 0.15em 0.45em; border-radius: 4px; font-size: 0.875em; font-family: 'Courier New', monospace; }
                .prose-blog pre { background: #0d1117; border: 1px solid rgba(34,197,94,0.2); border-radius: 12px; padding: 1rem 1.2rem; overflow-x: auto; margin-bottom: 1.5em; }
                .prose-blog pre code { background: none; border: none; padding: 0; color: #d1d5db; }
                .prose-blog blockquote { border-left: 3px solid #22c55e; padding-left: 1rem; color: #9ca3af; font-style: italic; margin: 1.5em 0; }
                .prose-blog a { color: #4ade80; text-decoration: underline; }
                .prose-blog a:hover { color: #86efac; }
                .prose-blog strong { color: #f9fafb; font-weight: 600; }
                .prose-blog hr { border-color: rgba(34,197,94,0.15); margin: 2em 0; }
                .prose-blog table { width: 100%; border-collapse: collapse; margin-bottom: 1.5em; }
                .prose-blog th { background: #0d1117; border: 1px solid rgba(34,197,94,0.2); color: #4ade80; padding: 0.5rem 0.75rem; text-align: left; }
                .prose-blog td { border: 1px solid rgba(34,197,94,0.1); padding: 0.5rem 0.75rem; }
            `}</style>
        </PageLayout>
    );
}
