import React from "react";
import { Typewriter } from "react-simple-typewriter";
import profileImage from "../logos/nachikethjoshi.jpg";

export default function ProfilePopup({ open, onClose }) {
    if (!open) return null;

    const aboutMeText = [
        "I am a results-oriented Data Scientist and aspiring Quant Researcher with a strong foundation in high-performance computing, advanced data structures, and mathematical modeling.",
        "My expertise lies in designing and optimizing scalable data pipelines, developing quantitative trading signals, and integrating predictive AI/ML models into enterprise systems.",
        "I thrive at the intersection of quantitative finance and cutting-edge software engineering, constantly seeking opportunities to apply advanced analytics to market challenges. Ready for the next high-impact role.",
    ];

    return (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50">
            <div className="bg-[#0b0f16] border border-green-400/40 rounded-2xl p-5 w-[90%] max-w-3xl shadow-[0_0_25px_rgba(34,197,94,0.4)] relative">
                <button
                    onClick={onClose}
                    className="absolute top-4 right-4 text-green-400 hover:text-red-400 text-lg transition"
                    aria-label="Close"
                >
                    ✕
                </button>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 p-5">
                    <div className="col-span-1 px-4 text-center lg:border-r lg:border-green-400/30 lg:block">
                        <img
                            src={profileImage}
                            alt="Nachiketh Joshi - Profile"
                            className="w-46 h-52 rectangle-full rounded-2xl object-cover mx-auto relative -translate-x-4 mb-4 border-2 border-green-200 shadow-[0_0_15px_rgba(34,197,94,0.6)]"
                        />
                        <div className="flex items-baseline mb-2 relative -translate-x-6">
                            <span className="text-[1.3rem] font-extrabold text-green-400 mr-2">Nachiketh</span>
                            <span className="text-[1.3rem] font-extrabold text-white">Joshi</span>
                        </div>
                        <div className="text-sm font-small text-left text-gray-300">
                            Masters in CS - USF
                        </div>
                    </div>

                    <div className="lg:col-span-2 text-left">
                        <h2 className="text-2xl font-semibold text-green-400 mb-3">Profile Summary</h2>
                        <div className="text-xs font-extra small text-green-300">
                            Quant Developer • Data Scientist • Software Engineer • AI Engineer
                        </div>
                        <div className="text-gray-300 text-base leading-relaxed min-h-[150px]">
                            <Typewriter
                                words={aboutMeText}
                                loop={true}
                                cursor
                                cursorStyle="▌"
                                typeSpeed={60}
                                deleteSpeed={30}
                                delaySpeed={2000}
                            />
                        </div>
                    </div>
                </div>

                <div className="mt-1 text-center text-gray-500 text-xs">
                    (Close this window or press '✕' to return to the main dashboard.)
                </div>
            </div>
        </div>
    );
}
