import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
    collection, addDoc, updateDoc, deleteDoc, doc,
    getDocs, orderBy, query, serverTimestamp,
} from "firebase/firestore";
import { signInWithEmailAndPassword, signOut, onAuthStateChanged } from "firebase/auth";
import { db, auth } from "../firebase";
import PageLayout from "../components/PageLayout";

const CATEGORIES = ["Quant", "ML/AI", "Research", "Tech", "General"];

const emptyForm = {
    title: "",
    summary: "",
    content: "",
    category: "General",
    tags: "",
    published: false,
};

function LoginForm({ onLogin }) {
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError("");
        setLoading(true);
        try {
            await signInWithEmailAndPassword(auth, email, password);
        } catch (err) {
            setError("Invalid credentials. Access restricted to author.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="max-w-sm mx-auto mt-10">
            <div className="bg-[#0d1117] border border-green-500/30 rounded-2xl p-8">
                <h2 className="text-green-400 text-2xl font-bold mb-1">Admin Access</h2>
                <p className="text-gray-500 text-sm mb-6">Restricted to blog author only.</p>
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-gray-400 text-xs mb-1 font-mono">Email</label>
                        <input
                            type="email"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required
                            className="w-full bg-[#0b0f16] border border-green-500/20 text-white rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-green-400 transition"
                        />
                    </div>
                    <div>
                        <label className="block text-gray-400 text-xs mb-1 font-mono">Password</label>
                        <input
                            type="password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                            className="w-full bg-[#0b0f16] border border-green-500/20 text-white rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-green-400 transition"
                        />
                    </div>
                    {error && <p className="text-red-400 text-xs">{error}</p>}
                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full bg-green-500 hover:bg-green-400 text-black font-bold py-2 rounded-lg text-sm transition disabled:opacity-50"
                    >
                        {loading ? "Signing in..." : "Sign In"}
                    </button>
                </form>
            </div>
        </div>
    );
}

function BlogEditor({ post, onSave, onCancel }) {
    const [form, setForm] = useState(post || emptyForm);
    const [saving, setSaving] = useState(false);

    const set = (key, val) => setForm((f) => ({ ...f, [key]: val }));

    const handleSave = async () => {
        if (!form.title.trim()) return;
        setSaving(true);
        try {
            const tagsArray = form.tags
                ? form.tags.split(",").map((t) => t.trim()).filter(Boolean)
                : [];
            const data = {
                title: form.title.trim(),
                summary: form.summary.trim(),
                content: form.content.trim(),
                category: form.category,
                tags: tagsArray,
                published: form.published,
                author: "Nachiketh Joshi",
            };
            if (post?.id) {
                await updateDoc(doc(db, "blogs", post.id), data);
            } else {
                await addDoc(collection(db, "blogs"), { ...data, date: serverTimestamp() });
            }
            onSave();
        } catch (err) {
            console.error("Save failed:", err);
        } finally {
            setSaving(false);
        }
    };

    const inputClass = "w-full bg-[#0b0f16] border border-green-500/20 text-white rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-green-400 transition";

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-[#0d1117] border border-green-500/30 rounded-2xl p-6 space-y-4"
        >
            <h3 className="text-green-400 font-bold text-lg">{post?.id ? "Edit Post" : "New Post"}</h3>

            <div>
                <label className="block text-gray-400 text-xs mb-1 font-mono">Title *</label>
                <input value={form.title} onChange={(e) => set("title", e.target.value)} className={inputClass} placeholder="Post title..." />
            </div>

            <div>
                <label className="block text-gray-400 text-xs mb-1 font-mono">Summary</label>
                <textarea value={form.summary} onChange={(e) => set("summary", e.target.value)} rows={2} className={inputClass} placeholder="Brief summary shown in the listing..." />
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div>
                    <label className="block text-gray-400 text-xs mb-1 font-mono">Category</label>
                    <select value={form.category} onChange={(e) => set("category", e.target.value)} className={inputClass}>
                        {CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-gray-400 text-xs mb-1 font-mono">Tags (comma-separated)</label>
                    <input value={form.tags} onChange={(e) => set("tags", e.target.value)} className={inputClass} placeholder="sharpe, crypto, ml..." />
                </div>
            </div>

            <div>
                <label className="block text-gray-400 text-xs mb-1 font-mono">Content (Markdown)</label>
                <textarea
                    value={form.content}
                    onChange={(e) => set("content", e.target.value)}
                    rows={18}
                    className={`${inputClass} font-mono text-xs leading-relaxed resize-y`}
                    placeholder={`# Heading\n\nWrite your post in **markdown**.\n\n## Section\n\nParagraphs, \`code\`, lists, and links all work.\n\n- Item one\n- Item two`}
                />
                <p className="text-gray-600 text-[10px] mt-1">Markdown is supported: # headings, **bold**, \`code\`, - lists, &gt; blockquotes</p>
            </div>

            <div className="flex items-center gap-3">
                <label className="flex items-center gap-2 cursor-pointer">
                    <input
                        type="checkbox"
                        checked={form.published}
                        onChange={(e) => set("published", e.target.checked)}
                        className="accent-green-500"
                    />
                    <span className="text-gray-300 text-sm">Published (visible to public)</span>
                </label>
            </div>

            <div className="flex gap-3 pt-2">
                <button
                    onClick={handleSave}
                    disabled={saving || !form.title.trim()}
                    className="bg-green-500 hover:bg-green-400 text-black font-bold px-5 py-2 rounded-lg text-sm transition disabled:opacity-50"
                >
                    {saving ? "Saving..." : (post?.id ? "Update Post" : "Publish Post")}
                </button>
                <button
                    onClick={onCancel}
                    className="border border-green-500/30 text-gray-400 hover:text-white hover:border-green-400 px-5 py-2 rounded-lg text-sm transition"
                >
                    Cancel
                </button>
            </div>
        </motion.div>
    );
}

export default function AdminPage() {
    const [user, setUser] = useState(null);
    const [posts, setPosts] = useState([]);
    const [editing, setEditing] = useState(null);
    const [showNew, setShowNew] = useState(false);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const unsub = onAuthStateChanged(auth, (u) => {
            setUser(u);
            setLoading(false);
        });
        return unsub;
    }, []);

    const fetchPosts = async () => {
        const q = query(collection(db, "blogs"), orderBy("date", "desc"));
        const snap = await getDocs(q);
        setPosts(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
    };

    useEffect(() => {
        if (user) fetchPosts();
    }, [user]);

    const handleDelete = async (id) => {
        if (!window.confirm("Delete this post? This cannot be undone.")) return;
        await deleteDoc(doc(db, "blogs", id));
        await fetchPosts();
    };

    const afterSave = () => {
        setEditing(null);
        setShowNew(false);
        fetchPosts();
    };

    if (loading) {
        return (
            <PageLayout>
                <div className="text-center py-20 text-gray-500 font-mono">Loading...</div>
            </PageLayout>
        );
    }

    if (!user) {
        return (
            <PageLayout>
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                    <div className="text-center mb-8">
                        <h1 className="text-3xl font-bold text-green-400 mb-2">Blog Admin</h1>
                        <div className="h-[2px] w-16 mx-auto bg-gradient-to-r from-transparent via-green-500 to-transparent rounded" />
                    </div>
                    <LoginForm />
                </motion.div>
            </PageLayout>
        );
    }

    return (
        <PageLayout>
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5 }}
            >
                <div className="flex items-center justify-between mb-8">
                    <div>
                        <h1 className="text-3xl font-bold text-green-400">Blog Admin</h1>
                        <p className="text-gray-500 text-sm mt-1">Signed in as {user.email}</p>
                    </div>
                    <div className="flex gap-3">
                        {!showNew && !editing && (
                            <button
                                onClick={() => setShowNew(true)}
                                className="bg-green-500 hover:bg-green-400 text-black font-bold px-4 py-2 rounded-lg text-sm transition"
                            >
                                + New Post
                            </button>
                        )}
                        <button
                            onClick={() => signOut(auth)}
                            className="border border-red-500/30 text-red-400 hover:bg-red-500/10 px-4 py-2 rounded-lg text-sm transition"
                        >
                            Sign Out
                        </button>
                    </div>
                </div>

                {/* Editor */}
                {(showNew || editing) && (
                    <div className="mb-8">
                        <BlogEditor
                            post={editing}
                            onSave={afterSave}
                            onCancel={() => { setEditing(null); setShowNew(false); }}
                        />
                    </div>
                )}

                {/* Posts list */}
                {!showNew && !editing && (
                    <div className="space-y-3">
                        {posts.length === 0 && (
                            <div className="text-center py-16 text-gray-500">
                                No posts yet. Click "+ New Post" to create your first one.
                            </div>
                        )}
                        {posts.map((post) => (
                            <div
                                key={post.id}
                                className="bg-[#0d1117] border border-green-500/20 rounded-xl p-4 flex items-start justify-between gap-4 hover:border-green-500/40 transition"
                            >
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 mb-1">
                                        <span className={`text-[10px] font-mono px-2 py-0.5 rounded-full border ${post.published ? "bg-green-500/10 border-green-500/30 text-green-400" : "bg-gray-500/10 border-gray-500/30 text-gray-500"}`}>
                                            {post.published ? "Published" : "Draft"}
                                        </span>
                                        {post.category && (
                                            <span className="text-gray-600 text-xs font-mono">{post.category}</span>
                                        )}
                                    </div>
                                    <h3 className="text-white font-semibold text-sm truncate">{post.title}</h3>
                                    {post.summary && (
                                        <p className="text-gray-500 text-xs mt-1 line-clamp-1">{post.summary}</p>
                                    )}
                                </div>
                                <div className="flex gap-2 shrink-0">
                                    <button
                                        onClick={() => setEditing(post)}
                                        className="border border-green-500/30 text-green-400 hover:bg-green-500/10 px-3 py-1.5 rounded-lg text-xs transition"
                                    >
                                        Edit
                                    </button>
                                    <button
                                        onClick={() => handleDelete(post.id)}
                                        className="border border-red-500/20 text-red-400 hover:bg-red-500/10 px-3 py-1.5 rounded-lg text-xs transition"
                                    >
                                        Delete
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </motion.div>
        </PageLayout>
    );
}
