import React, { useState } from "react";
import { Link } from "react-router-dom";
import { ArrowLeft } from "lucide-react";
import LeftNavBar from "./LeftNavBar";
import MessagePopup from "./MessagePopup";
import ProfilePopup from "./ProfilePopup";

export default function PageLayout({ children, title }) {
    const [showForm, setShowForm] = useState(false);
    const [showProfile, setShowProfile] = useState(false);

    return (
        <div className="min-h-screen bg-[#0b0f16] bg-grid text-white flex flex-col items-center px-6 relative overflow-hidden">
            <LeftNavBar
                onConnect={() => setShowForm(true)}
                onProfile={() => setShowProfile(true)}
            />
            <MessagePopup open={showForm} onClose={() => setShowForm(false)} />
            <ProfilePopup open={showProfile} onClose={() => setShowProfile(false)} />

            <div className="w-full max-w-5xl pt-16 pb-16">
                <div className="flex items-center gap-3 mb-8 mt-4">
                    <Link
                        to="/"
                        className="flex items-center gap-2 text-green-400 hover:text-green-300 transition text-sm font-mono border border-green-500/30 px-3 py-1.5 rounded-lg hover:bg-green-500/10"
                    >
                        <ArrowLeft size={14} />
                        Back to Portfolio
                    </Link>
                </div>
                {children}
            </div>
        </div>
    );
}
