    React.useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 640);
        window.addEventListener("resize", handleResize);
        return () => window.removeEventListener("resize", handleResize);
    }, []);

    React.useEffect(() => {
        const node = chartRef.current;
        if (!node) return;

        const startAnimation = () => {
            if (animIntervalRef.current) clearInterval(animIntervalRef.current);
            completedRef.current = false;
            setRevealIndex(1);
            animIntervalRef.current = setInterval(() => {
                setRevealIndex((idx) => {
                    const next = Math.min(idx + 1, CHART_DATA.length);
                    if (next === CHART_DATA.length) {
                        clearInterval(animIntervalRef.current);
                        animIntervalRef.current = null;
                        completedRef.current = true;
                    }
                    const pt = CHART_DATA[next - 1];
                    if (pt?.isMilestone && pt?.milestone?.includes("2023")) {
                        setComet(true);
                        setTimeout(() => setComet(false), 900);
                    }
                    return next;
                });
            }, 150);
        };

        const observer = new IntersectionObserver(
            (entries) => {
                const entry = entries[0];
                if (entry.isIntersecting) {
                    // Entered viewport — animate if not already running
                    if (!animIntervalRef.current && !completedRef.current) {
                        startAnimation();
                    }
                } else {
                    // Left viewport — stop any in-progress animation and reset so
                    // the next visit triggers a fresh re-animation
                    if (animIntervalRef.current) {
                        clearInterval(animIntervalRef.current);
                        animIntervalRef.current = null;
                    }
                    completedRef.current = false;
                    setRevealIndex(1);
                    setComet(false);
                }
            },
            { threshold: 0.3 }
        );

        observer.observe(node);
        return () => {
            observer.disconnect();
            if (animIntervalRef.current) clearInterval(animIntervalRef.current);
        };
    }, []);

