import React, { useState } from "react";
import { motion } from "framer-motion";
import PageLayout from "../components/PageLayout";
import { PROJECTS } from "../data/projects";

const TAG_COLORS = {
    green: "bg-green-500/10 border-green-500/30 text-green-400",
    blue: "bg-blue-500/10 border-blue-500/30 text-blue-300",
    purple: "bg-purple-500/10 border-purple-500/30 text-purple-300",
};

const CATEGORIES = ["All", ...Array.from(new Set(PROJECTS.map((p) => p.category)))];

export default function ProjectsPage() {
    const [activeCategory, setActiveCategory] = useState("All");

    const filtered = activeCategory === "All"
        ? PROJECTS
        : PROJECTS.filter((p) => p.category === activeCategory);

    return (
        <PageLayout>
            <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6 }}
            >
                <div className="text-center mb-10">
                    <h1 className="text-4xl font-bold text-green-400 mb-2">Projects</h1>
                    <div className="h-[2px] w-16 mx-auto mb-4 bg-gradient-to-r from-transparent via-green-500 to-transparent rounded" />
                    <p className="text-gray-400 text-sm">
                        Quant research, ML systems, and engineering projects
                    </p>
                </div>

                {/* Category filter */}
                <div className="flex flex-wrap justify-center gap-2 mb-8">
                    {CATEGORIES.map((cat) => (
                        <button
                            key={cat}
                            onClick={() => setActiveCategory(cat)}
                            className={`px-4 py-1.5 rounded-full text-sm font-mono border transition-all duration-200 ${
                                cat === activeCategory
                                    ? "bg-green-500/20 border-green-400 text-green-300 shadow-[0_0_10px_rgba(34,197,94,0.3)]"
                                    : "border-green-500/20 text-gray-500 hover:border-green-500/40 hover:text-gray-300"
                            }`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>

                {/* Project grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {filtered.map((project, i) => (
                        <motion.div
                            key={project.id}
                            initial={{ opacity: 0, y: 30 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ duration: 0.4, delay: i * 0.08 }}
                            className="bg-[#0b0f16] border border-green-500/40 rounded-2xl p-6 text-left hover:border-green-400 hover:shadow-[0_0_18px_rgba(34,197,94,0.4)] transition relative"
                        >
                            {/* Pinned badge */}
                            {project.pinned && (
                                <span className="absolute top-4 right-4 bg-green-500/20 border border-green-500/40 text-green-400 text-[10px] font-mono px-2 py-0.5 rounded-full flex items-center gap-1">
                                    📌 Featured
                                </span>
                            )}

                            <div className="flex items-start gap-2 mb-1">
                                <span className="text-gray-500 text-xs font-mono bg-[#0d1117] border border-green-500/10 px-2 py-0.5 rounded">
                                    {project.category}
                                </span>
                                <span className="text-gray-600 text-xs font-mono">{project.year}</span>
                            </div>

                            <h3 className="text-green-400 text-lg font-semibold mt-2 mb-3 leading-snug pr-16">
                                {project.title}
                            </h3>

                            <ul className="list-disc list-inside text-gray-300 space-y-1 text-sm mb-4">
                                {project.details.map((d, idx) => (
                                    <li key={idx}>{d}</li>
                                ))}
                            </ul>

                            <div className="flex flex-wrap gap-2 pt-4 border-t border-green-500/20">
                                {project.tags.map((tag) => (
                                    <span
                                        key={tag.label}
                                        className={`border text-xs px-2.5 py-1 rounded-full font-mono ${TAG_COLORS[tag.color] || TAG_COLORS.green}`}
                                    >
                                        {tag.label}
                                    </span>
                                ))}
                            </div>
                        </motion.div>
                    ))}
                </div>
            </motion.div>
        </PageLayout>
    );
}
